CREATE TABLE `users` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `username` varchar(32) NOT NULL COMMENT '用户名',
  `password` varchar(64) NOT NULL COMMENT 'MD5加盐密码',
  `salt` varchar(32) DEFAULT NULL COMMENT '每用户随机盐(SHA-256 哈希用)',
  `pwd_cipher` varchar(128) DEFAULT NULL COMMENT '瀵嗙爜鍙??瀵嗘枃(AES), 浠呬緵绠＄悊鍛樻煡鐪? 鐧诲綍鏍￠獙涓嶄娇鐢',
  `nickname` varchar(32) NOT NULL DEFAULT '新手召唤师',
  `rating` int NOT NULL DEFAULT '1000' COMMENT '天梯积分',
  `win_count` int NOT NULL DEFAULT '0',
  `lose_count` int NOT NULL DEFAULT '0',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `role` varchar(20) NOT NULL DEFAULT 'user',
  `balance` int NOT NULL DEFAULT '0',
  `crystal` int NOT NULL DEFAULT '0' COMMENT '水晶(签到/任务获得)',
  `skin_id` int NOT NULL DEFAULT '0',
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '0正常 1封禁',
  `banned_until` datetime DEFAULT NULL,
  `ban_reason` varchar(200) DEFAULT NULL COMMENT '封禁原因',
  `avatar` varchar(200) DEFAULT NULL COMMENT '头像路径',
  `phone` varchar(20) DEFAULT NULL COMMENT '手机号',
  PRIMARY KEY (`id`),
  UNIQUE KEY `username` (`username`),
  UNIQUE KEY `uk_phone` (`phone`),
  KEY `idx_status` (`status`),
  KEY `idx_ct` (`create_time`)
) ENGINE=InnoDB AUTO_INCREMENT=9002 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='用户表';
